#!/usr/bin/env bash
# Downloads Syzygy endgame tablebases (WDL and DTZ files) from the Lichess mirror.
#
#   scripts/download-syzygy.sh <directory> [test|3-4-5]
#
# `test` (the default) fetches a handful of small 3- and 4-piece tables, enough for the
# cb2026-syzygy tests (a few MB); CI runs this. `3-4-5` fetches the full 3-, 4- and 5-piece set
# (about 1 GB) for real play: point the engine's SyzygyPath option (or the shell's
# `set syzygy`) at the directory. Files already present are skipped. The tables are never
# committed to the repository.
#
# Syzygy tables were generated by Ronald de Man and are free to use.
set -euo pipefail

if [[ $# -lt 1 || "$1" == "-h" || "$1" == "--help" ]]; then
  sed -n '2,12p' "$0"
  exit 2
fi
DIR="$1"
SET="${2:-test}"
# The mirror keeps the WDL files (.rtbw) and the DTZ files (.rtbz) in separate directories.
# They used to share one, `3-4-5`, which answers 404 now (found 2026-10-23).
BASE="https://tablebase.lichess.ovh/tables/standard"
WDL="$BASE/3-4-5-wdl"
DTZ="$BASE/3-4-5-dtz"
mkdir -p "$DIR"

fetch() {
  local file="$1" from
  if [[ -s "$DIR/$file" ]]; then
    return
  fi
  case "$file" in
    *.rtbw) from="$WDL" ;;
    *.rtbz) from="$DTZ" ;;
  esac
  echo "Downloading $file"
  curl -fsSL --retry 3 -o "$DIR/$file.part" "$from/$file"
  mv "$DIR/$file.part" "$DIR/$file"
}

case "$SET" in
  test)
    for table in KQvK KRvK KPvK KRvKR; do
      fetch "$table.rtbw"
      fetch "$table.rtbz"
    done
    ;;
  3-4-5)
    # Each directory listing names its files; fetch each table they link to.
    for listing in "$WDL" "$DTZ"; do
      curl -fsSL "$listing/" | grep -oE 'href="K[A-Za-z]*v[A-Za-z]*\.rtb[wz]"' | cut -d'"' -f2 |
        while read -r file; do
          fetch "$file"
        done
    done
    ;;
  *)
    echo "download-syzygy: unknown set '$SET' (use test or 3-4-5)" >&2
    exit 2
    ;;
esac
echo "Tables in $DIR: $(find "$DIR" -name '*.rtb?' | wc -l | tr -d ' ') files"
